#define kWS		kWordSep		// set if char qualifies as a word separator (i.e. space char)
#define kPed	kPeriod			// set if char qualifies as a period/decimal
#define kCom	kComma			// set if char qualifies as a comma
#define kApot	kApostrophe		// set if char qualifies as an apostrophe
#define kPunc 	kPuncMark		// set if char qualifies as punctuation
#define kOthr	kOther			// set if char doesn't fall in other categories
#define kLet 	kLetter			// set if char is a-z or A-Z
#define kDig	kDigit			// set if char is 0-9


const short	CHAR_ATTR_FLAGS[] =
{
//	Control characters

	0,				kWS,			kWS,			kWS,			kWS,			kWS,			kWS,			kWS,
	kWS,			kWS,			kWS,			kWS,			kWS,			kWS,			kWS,			kWS,
	kWS,			kWS,			kWS,			kWS,			kWS,			kWS,			kWS,			kWS,
	kWS,			kWS,			kWS,			kWS,			kWS,			kWS,			kWS,			kWS,

//	space			!				"				#				$				%				&				'				
	kWS,			kPunc,			kOthr,			kOthr,			kOthr,			kOthr,			kOthr,			kApot,
		
//	(				)				//				+				,				-				.				/				
	kOthr,			kOthr,			kOthr,			kOthr,			kPunc+kCom,		kPunc+kDash,	kPunc+kPed,		kOthr,				

//	0				1				2				3				4				5				6				7		
	kDig,			kDig,			kDig,			kDig,			kDig,			kDig,			kDig,			kDig,

//	8				9				:				;				<				=				>				?				
	kDig,			kDig,			kPunc,			kPunc,			kOthr,			kOthr,			kOthr,			kPunc,

//	@				A				B				C				D				E				F				G				
	kOthr,			kLet+kCap+kVow,	kLet+kCap,		kLet+kCap,		kLet+kCap,		kLet+kCap+kVow,	kLet+kCap,		kLet+kCap,

//	H				I				J				K				L				M				N				O				
	kLet+kCap,		kLet+kCap+kVow,	kLet+kCap,		kLet+kCap,		kLet+kCap,		kLet+kCap,		kLet+kCap,		kLet+kCap+kVow,

//	P				Q				R				S				T				U				V				W				
	kLet+kCap,		kLet+kCap,		kLet+kCap,		kLet+kCap,		kLet+kCap,		kLet+kCap+kVow,	kLet+kCap,		kLet+kCap,

//	X				Y				Z				[				bslash				]				^				_				
	kLet+kCap,		kLet+kCap+kVow,	kLet+kCap,		kOthr,			kOthr,			kOthr,			kOthr,			kPunc,

//	`				a				b				c				d				e				f				g				
	kOthr,			kLet+kVow,		kLet,			kLet,			kLet,			kLet+kVow,		kLet,			kLet,

//	h				i				j				k				l				m				n				o				
	kLet,			kLet+kVow,		kLet,			kLet,			kLet,			kLet,			kLet,			kLet+kVow,

//	p				q				r				s				t				u				v				w				
	kLet,			kLet,			kLet,			kLet,			kLet,			kLet+kVow,		kLet,			kLet,

//	x				y				z				{				|				}				~				delete
	kLet,			kLet+kVow,		kLet,			kOthr,			kWS,			kOthr,			kOthr,			kOthr
	
};



